pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});


pm.test("All posts have non-empty title and body", function () {
    const posts = pm.response.json();

    posts.forEach((post) => {
        pm.expect(post.title).to.be.a('string').and.not.empty;
        pm.expect(post.body).to.be.a('string').and.not.empty;
    });
});


pm.test("No title or body contains the word 'zombie'", function () {
    const posts = pm.response.json();

    posts.forEach((post) => {
        pm.expect(post.title.toLowerCase()).to.not.include('zombie');
        pm.expect(post.body.toLowerCase()).to.not.include('zombie');
    });
});

pm.test("Status code is 200 or 201", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

pm.test("Topping contains bacon, cheese and mushroom", function () {
    const responseBody = pm.response.json();
    const topping = responseBody.json.topping;

    pm.expect(topping).to.include.members(['bacon', 'cheese', 'mushroom']);
});

pm.test("Topping does not contain chicken", function () {
    const responseBody = pm.response.json();
    const topping = responseBody.json.topping;

    pm.expect(topping).to.not.include('chicken');
});
